package com.example.helpdesk.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="ticket_history") public class TicketHistory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="ticket_id") private Ticket ticket; @ManyToOne(optional=false) @JoinColumn(name="actor_id") private User actor; @Column(nullable=false) private String action; private String details; @Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now(); public TicketHistory(){} public TicketHistory(Ticket t,User a,String x,String d){ticket=t;actor=a;action=x;details=d;} public String getAction(){return action;} public String getDetails(){return details;} public LocalDateTime getCreatedAt(){return createdAt;} public User getActor(){return actor;} }
